    "kind": "简答",
    "stem": "【预测卷二·简答第49题｜\"教育是社会的复制工具\"与\"教育是社会变革的引擎\"】有学者认为“教育是社会的复制工具”，也有学者主张“教育是社会变革的引擎”。请谈谈你对这两种观点的理解，并分析教育在社会发展中的合理定位。",
    "options": {},
    "answer": "",
    "analysis": "作答骨架：\n\"复制工具\"说的是社会对教育的制约：教育的目的、内容、制度受生产力水平和政治经济制度制约，所以教育客观上具有维护和再生产现有社会结构的功能，呈现\"复制\"的一面。\n\"变革引擎\"说的是教育对社会的促进：教育培养有创新精神和批判意识的人，传播新观念、更新生产技术，对政治经济产生强大推动，呈现\"变革\"的一面。\n合理定位：基于教育的相对独立性，教育在社会中的定位是双重的——既受社会制约，又相对独立；既维持社会稳定，又推动社会良性变革。所以教育不能只复制现实而拒绝变革，也不能脱离现实空谈变革。\n钩子：一只脚站在社会给的地板上（复制），一只手推着社会往前走（变革）。"
