    "stem": "【预测卷二·简答第52题｜负强化与惩罚的区别，及李老师做法的性质】为了让学生不再迟到，李老师规定：谁迟到，就取消他当天的课间休息。请判断李老师的行为属于负强化还是惩罚，并说明负强化和惩罚的区别。",
    "options": {},
    "answer": "",
    "analysis": "作答骨架：\n负强化：撤销某种厌恶刺激，使行为发生概率增加。惩罚：呈现厌恶刺激或撤销愉快刺激，使行为发生概率降低。\n李老师的做法属于惩罚：学生迟到后剥夺他喜欢的课间休息，是撤销愉快刺激来减少迟到，属惩罚，不是负强化。\n三点区别：刺激上，负强化撤厌恶刺激，惩罚是给厌恶刺激或撤愉快刺激；效果上，负强化增加行为，惩罚减少行为；应用上，负强化保持良性行为，惩罚消除不良行为。\n钩子：负强化＝\"拿走坏的，好事更多\"；惩罚＝\"给点苦头或拿走甜头，坏事更少\"。都\"减\"了点东西，但一个是减痛苦，一个是减快乐。"
