    "analysis": "作答骨架：\n核心判断：从\"知\"到\"行\"不是自动的，中间要靠\"情\"来驱动、靠\"意\"来支撑；知情意行任一环薄弱，都会脱节。\n第一，现实情境复杂，知与行会有价值冲突：个人利益与道德认知相撞时，人可能明知该做却趋利避害而不做。\n第二，道德情感驱动不足：情感是连接知与行的核心中介，认知若没有伴随积极的情感体验，就难主动付诸行动。\n第三，道德意志调控不足：行为实现要靠意志克服诱惑、惰性和阻碍，光有认知、没有意志，就稳不住一贯的行为。\n第四，四要素是有机整体：知情意行互为条件、相互支撑，单个要素成熟替代不了整体发展。\n钩子：知是方向盘，情是油门，意是刹车与定力，行是车轮。缺油门车不走，缺定力车跑偏。"
