    "category": "预测卷三",
    "number": 164,
    "type": "open",
    "kind": "简答",
    "stem": "【预测卷三·简答第50题｜课程资源的特点（结合材料归纳）】结合材料，简述真正的课程资源区别于传统教科书的基本特征。课程资源绝非仅仅是教材或文本形式的资源。真正的课程资源对学生的发展具有独特的价值，它具有丰富性、开放性、具体形象、生动活泼、可供学生亲自参与等特点。它能为学生提供多方面的信息刺激，调动学生多种感官参与活动，激发学生兴趣，使学生身临其境，在愉悦中增长知识、培养能力、陶冶情操。这是传统教科书所无法代替的。",
