    "stem": "【预测卷三·简答第51题｜为什么说柏拉图与福禄培尔是\"两个重大例外\"】请说明材料中杜威认为柏拉图和福禄培尔是重大例外的原因。杜威曾高度评价福禄培尔的游戏思想。他说：“游戏是如此出自自然的和不可避免的，以致很少有教育著作家从理论上赋予它在实际中所占的地位，或者试图弄明白，儿童自发的游戏活动能否提出一些可供学校采纳的启示。只有古代的柏拉图和近代的福禄培尔算是两个重大的例外。”",
