    "analysis": "作答骨架：\n区别：显性知识能被清晰表达、编码、记录和传递，客观、有逻辑、易传播；隐性知识高度个人化，难以形式化、难以直接说清，是\"只可意会不可言传\"的技能与诀窍。\n联系（相互依存、可转化）：显性知识是隐性知识的基础和载体——隐性能借比喻、概念、语言外化成显性；隐性知识是显性知识的源泉和归宿——显性要经过实践与反思内化成个人经验、直觉、诀窍才能真正指导实践；此外还有两种同质转化：隐性知识社会化（观察模仿习得他人的隐性知识）、显性知识综合化（把零散显性知识整理成系统）。四种模式循环往复，推动知识丰富与创新。\n钩子：外化（隐→显）、内化（显→隐）、社会化（隐→隐）、综合化（显→显）。"
