    "kind": "论述",
    "stem": "【预测卷三·论述第56II题｜实验研究题：特朗普制】\nⅡ. 阅读材料，并按要求回答问题。在一项名为“特朗普制的教学效果实验”的研究中，研究者选择了某市一所普通中学的初二\n（4）班为实验班（60人），初二\n（7）班为控制班（52人），两班学生成绩的平均分相当，两班教师水平相当，所用教材相同，图书资源、实验设备、计算机房均共用。在实验班采用特朗普制，即使用弹性模块式时间表，将上课时间划分为大班教学时间（占40%）、小组讨论时间（占40%）和独立学习时间（占20%），三者的组合可以灵活调整。控制班则采用传统班级授课制，即教师讲、学生听的方法。实验周期为一学期。研究者根据实验前后两班学生测试成绩的差异来判断特朗普制的教学效果。\n请回答：(1）该实验的假设、自变量和因变量分别是什么？（3分）(2）请写出该实验设计类型的名称和格式。（4分）\n（3）该实验控制无关变量的主要措施是什么？（8分）\n（4）实验后测发现：实验班的平均分为80分，控制班的平均分为73分，两班成绩的标准差分别为18分和15分，两班平均成绩差异的Z值为2.19。此外，实验班前后测平均成绩差异的Z值为2.08。根据测试数据，可得出什么研究结论？（10分）\n（5）请说出该实验分组可能存在的问题，并提出分组的改进方案。（5分）全国硕士研究生招生考试教育学专业基础（科目代码：311)题卡指定位置的边框区域内。超出答题区域书写的答案无效；在草稿纸、试题册上答题无效。4.填（书）写部分必须使用黑色字迹签字笔书写，字迹工整、笔迹清楚；涂写部分必须使用2B铅笔填涂。（以下信息考生必须认真填写）处呈现仅为提醒考生在考场上仔细阅读考试要求，认真填写信息！",
    "options": {},
