    "kind": "简答",
    "stem": "【预测卷六·简答第50题｜美育的直接途径与间接途径】简述材料中学校的做法所体现的美育实施途径。某中学过去的美育基本停留在“音乐课唱歌、美术课画画”的层面，且只重点培养少数艺术特长生。在《教育部关于全面实施学校美育浸润行动的通知》印发后，学校开设了“行走的美育课”：语文课上引导学生品读诗词意境，数学课上带领学生感受对称与比例之美，劳动课上指导学生用废旧材料制作手工作品；每月组织一次校外美育活动，带领学生去公园写生、参观博物馆、走进非遗工坊；在校园走廊定期展示普通学生的摄影、绘画、手工和书法作品。学校发现，学生的行为习惯、环保意识和班级氛围都有了明显改善。",
