    "stem": "【预测卷六·简答第52题｜老奶奶用奖励赶走孩子的例子｜自我决定理论】请运用相关动机理论解释材料中的现象。小区里有几个孩子闲来无事，总以踢金属设备为乐，发出的响声十分刺耳，该行为屡禁不止。一位老奶奶见状，承诺他们每天过来踢金属设备就可获得5元报酬。一周后，老奶奶以“钱已花光”为由停止支付报酬，孩子们便再也不去踢金属设备了。",
